 count(*) FILTER (WHERE q.id IN (SELECT id FROM v_safe_for_beta)) AS in_vsafe,
 count(*) FILTER (WHERE NOT q.is_public) AS not_public,
 count(*) FILTER (WHERE q.id IN (SELECT id FROM v_safe_for_beta_unfiltered)) AS in_unfiltered,
 count(*) FILTER (WHERE q.pipeline_metadata::jsonb ? 'match_tier' AND (q.pipeline_metadata::jsonb->>'match_tier') IN ('tier1_page_inline','tier1b_position_page_inline')) AS is_tier1,
